initJs:
function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#select-user");
        userSelect.innerHTML = '<option value="">すべてのユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const userName = getUserName(row.ユーザーID);
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const resultClass = row.処理結果 === '成功' ? 'success' : row.処理結果 === '失敗' ? 'error' : '';

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td><span style="color: ${resultClass === 'success' ? '#28a745' : resultClass === 'error' ? '#dc3545' : 'var(--text)'};">${row.処理結果 || ''}</span></td>
          <td>${row.処理時間 || ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : userId || '';
  }

  // ページネーション処理
  function renderPagination() {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageData = filteredData.slice(startIndex, endIndex);

    renderRows(pageData);

    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${Math.max(totalPages, 1)}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // 検索フィルター処理
  function applyFilters() {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const userId = container.querySelector("#select-user").value;
    const operationType = container.querySelector("#select-operation-type").value;
    const screenName = container.querySelector("#input-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#input-ip-address").value;
    const result = container.querySelector("#select-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を入力してください');
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIpAddress(ipAddress)) {
      alert('正しいIPアドレス形式で入力してください');
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate && row.操作日時 && new Date(row.操作日時) < new Date(startDate)) return false;
      if (endDate && row.操作日時 && new Date(row.操作日時) > new Date(endDate)) return false;

      // ユーザーフィルター
      if (userId && row.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && row.操作種別 !== operationType) return false;

      // 画面名・機能名検索
      if (screenName && !(row.操作画面 || '').toLowerCase().includes(screenName)) return false;

      // IPアドレス検索
      if (ipAddress && !(row.IPアドレス || '').includes(ipAddress)) return false;

      // 処理結果フィルター
      if (result && row.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderPagination();
  }

  // IPアドレスバリデーション
  function isValidIpAddress(ip) {
    // IPv4の正規表現
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    // IPv6の簡易正規表現
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;

    return ipv4Regex.test(ip) || ipv6Regex.test(ip);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const modal = container.querySelector("#detail-modal");
    const content = container.querySelector("#detail-content");

    const userName = getUserName(history.ユーザーID);
    const operationDate = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: 150px 1fr; gap: 12px; line-height: 1.6;">
        <div style="font-weight: bold; color: var(--text);">操作日時:</div>
        <div style="color: var(--text);">${operationDate}</div>

        <div style="font-weight: bold; color: var(--text);">ユーザー名:</div>
        <div style="color: var(--text);">${userName}</div>

        <div style="font-weight: bold; color: var(--text);">操作種別:</div>
        <div style="color: var(--text);">${history.操作種別 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作画面:</div>
        <div style="color: var(--text);">${history.操作画面 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作対象テーブル:</div>
        <div style="color: var(--text);">${history.操作対象テーブル || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作対象ID:</div>
        <div style="color: var(--text);">${history.操作対象ID || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作内容:</div>
        <div style="color: var(--text); word-break: break-all;">${history.操作内容 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">IPアドレス:</div>
        <div style="color: var(--text);">${history.IPアドレス || ''}</div>

        <div style="font-weight: bold; color: var(--text);">ユーザーエージェント:</div>
        <div style="color: var(--text); word-break: break-all;">${history.ユーザーエージェント || ''}</div>

        <div style="font-weight: bold; color: var(--text);">処理結果:</div>
        <div style="color: var(--text);">${history.処理結果 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">エラーメッセージ:</div>
        <div style="color: var(--text);">${history.エラーメッセージ || ''}</div>

        <div style="font-weight: bold; color: var(--text);">処理時間:</div>
        <div style="color: var(--text);">${history.処理時間 || ''}ms</div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // CSV出力
  function exportToCSV() {
    if (filteredData.length === 0) {
      alert('出力可能なデータがありません');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...filteredData.map(row => {
        const userName = getUserName(row.ユーザーID);
        const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';

        return [
          `"${operationDate}"`,
          `"${userName}"`,
          `"${row.操作種別 || ''}"`,
          `"${row.操作画面 || ''}"`,
          `"${row.操作対象テーブル || ''}"`,
          `"${row.操作対象ID || ''}"`,
          `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
          `"${row.IPアドレス || ''}"`,
          `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${row.処理結果 || ''}"`,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${row.処理時間 || ''}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadUsers();

    try {
      const rows = await window.aivicApi.list(13); // システム操作履歴テーブル
      if (rows) {
        allHistoryData = rows.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredData = [...allHistoryData];
        renderPagination();
      } else {
        // API未接続時は初期データを使用
        allHistoryData = tables[13]?.records || [];
        filteredData = [...allHistoryData];
        renderPagination();
      }
    } catch (error) {
      console.error('操作履歴データの取得に失敗しました:', error);
      allHistoryData = tables[13]?.records || [];
      filteredData = [...allHistoryData];
      renderPagination();
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-start-date").value = '';
    container.querySelector("#input-end-date").value = '';
    container.querySelector("#select-user").value = '';
    container.querySelector("#select-operation-type").value = '';
    container.querySelector("#input-screen-name").value = '';
    container.querySelector("#input-ip-address").value = '';
    container.querySelector("#select-result").value = '';

    filteredData = [...allHistoryData];
    currentPage = 1;
    renderPagination();
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportToCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderPagination();
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderPagination();
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add('hidden');
    }
  });

  // 初期化
  loadInitialData();
}
